function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 200) return 'nums needs 1 to 200 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each value is an integer from 1 to 10^6.';
  if (!Number.isInteger(k) || k < 0 || k > nums.length - 1) return 'k is between 0 and nums.length - 1.';
  return null;
}

