function minSpaceWastedKResizing(nums, k) {
  const n = nums.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(k + 2).fill(Infinity));
  dp[0][0] = 0;

  for (let end = 1; end <= n; end++) {
    let high = 0;
    let sum = 0;
    for (let start = end; start >= 1; start--) {
      high = Math.max(high, nums[start - 1]);
      sum += nums[start - 1];
      const waste = high * (end - start + 1) - sum;
      for (let segments = 1; segments <= k + 1; segments++) {
        const candidate = dp[start - 1][segments - 1] + waste;
        if (candidate < dp[end][segments]) {
          dp[end][segments] = candidate;
        }
      }
    }
  }
  return Math.min(...dp[n]);
}

