function minSpaceWastedKResizing(nums, k) {
  const n = nums.length;
  let best = Infinity;
  // Bit i of mask set means the capacity changes right before moment i + 1.
  for (let mask = 0; mask < (1 << (n - 1)); mask++) {
    let cuts = 0;
    for (let b = 0; b < n - 1; b++) if (mask & (1 << b)) cuts++;
    if (cuts > k) continue;
    let total = 0;
    let from = 0;
    for (let t = 0; t < n; t++) {
      if (t === n - 1 || (mask & (1 << t))) {
        const part = nums.slice(from, t + 1);
        const cap = Math.max(...part);
        for (const v of part) total += cap - v;
        from = t + 1;
      }
    }
    best = Math.min(best, total);
  }
  return best;
}

