function generate(rand, size) {
  const n = size === 'large' ? 200 : 1 + Math.floor(rand() * 9);
  const top = size === 'large' ? 1000000 : (rand() < 0.5 ? 5 : 40);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  if (size === 'large' && rand() < 0.5) nums.sort((a, b) => a - b);
  const k = size === 'large' ? Math.floor(rand() * (rand() < 0.5 ? 10 : n)) : Math.floor(rand() * n);
  return [nums, k];
}
